UPDATE ics31_compliance_write
   SET ics31_confirm_yn = #{confirmYn},
       ics31_confirmer_id = #{confirmerId},
       ics31_confirm_datetime = CASE WHEN #{confirmYn} = 'true' THEN f_sysdate() ELSE NULL END
 WHERE ics31_compliance_write_id = #{complianceWriteId}
   AND ics31_company_id = #{companyId}
